  ui_story_5059_50590101_26_dialog_content = "Ada apa? Aku yakin hiburannya sudah siap, jangan bilang kamu membawa sesuatu yang aneh?",
  ui_story_5059_50590101_27_dialog_content = "Terima kasih sudah datang! Itu baru pemanasan, akan diikuti oleh \"acara utama\"!",
  ui_story_5059_50590101_28_dialog_content = "Apa yang kamu lihat ini adalah apa yang sedang aku susun sekarang. Aku menyebutnya \"Tantangan Rapport 4\"!",
  ui_story_5059_50590101_29_dialog_content = "Kamu harus tahu bahwa permainan ini menyebabkan beberapa komandan saling bertarung, dan bahkan saya meningkatkannya untuk pertemuan ini.",
  ui_story_5059_50590101_30_dialog_content = "Apa? Ini tidak akan memicu pertengkaran lain, kan?",
