  ui_story_5059_50590102_7_dialog_content = "Yang lainnya? Mereka pergi ke tempat lain untuk bersantai setelah kekenyangan.",
  ui_story_5059_50590102_8_dialog_content = "Saya punya ide di mana mereka pergi, tapi saya tidak akan memberitahumu dengan mudah, PlayerName.",
