  ui_story_5059_50590102_10_dialog_content = "Jadi, kau mau apa?",
  ui_story_5059_50590102_11_dialog_content = "Cukup buktikan bahwa kamu memahami saya dengan baik di Rapport Challenge 4.",
  ui_story_5059_50590102_12_dialog_content = "Bagaimana menurutmu? Mempunyai hubungan baik dengan naga pasti sesuatu yang bisa dibanggakan.",
  ui_story_5059_50590102_13_dialog_content = "Oke, aku memang ingin bermain game ini bersama semua orang.",
  ui_story_5059_50590102_14_dialog_content = "Tidak seru hanya bermain berdua saja. Biarkan aku mendapatkan beberapa Aurorian lagi.",
  ui_story_5059_50590102_15_dialog_content = "Ekor Tohru adalah makanan terbaik di dunia!",
  ui_story_5059_50590102_16_dialog_content = "Ya.",
  ui_story_5059_50590102_17_dialog_content = "Kusadari ternyata tingkat kesulitan pertanyaan-pertanyaan ini hampir tidak ada.",
  ui_story_5059_50590102_18_dialog_content = "Tetap saja, jangan meremehkan saya!",
  ui_story_5059_50590102_19_dialog_content = "Tapi saya harus mengakui, saya tidak menyangka Beryl bisa mendapatkan jawaban yang benar begitu mudah.",
  ui_story_5059_50590102_20_dialog_content = "Hee, itu karena Tohru pernah menyebutkan padaku bahwa dia menyajikan ekornya untuk Kobayashi.",
  ui_story_5059_50590102_21_dialog_content = "Lezat dan menggugah selera! Kobayashi sangat menyukainya!",
  ui_story_5059_50590102_22_dialog_content = "Tunggu, kamu bilang waktu itu bahwa Kobayashi menolak untuk memakannya!",
  ui_story_5059_50590102_23_dialog_content = "Itu karena dia berpura-pura malu-malu!",
  ui_story_5059_50590102_24_dialog_content = "Kamu benar-benar suka menceritakan cerita itu, Tohru.",
  ui_story_5059_50590102_25_dialog_content = "Kurasa orang-orang tidak keberatan mendengar tentang kehidupan manisku bersama Kobayashi lebih dari sekali.",
  ui_story_5059_50590102_26_dialog_content = "Tidak.",
  ui_story_5059_50590102_27_dialog_content = "Tidak bisa dipercaya! Kamu tidak tahu betapa lezatnya ini!",
  ui_story_5059_50590102_28_dialog_content = "Yah, itu terdengar cukup menakutkan, cukup untuk membuat saya tidak ingin mencobanya sama sekali.",
  ui_story_5059_50590102_29_dialog_content = "Kamu nggak bisa makan sesuatu seperti ekor, kan...?",
  ui_story_5059_50590102_30_dialog_content = "Rasanya akan membuatmu terkesima! Anda bahkan bisa menyebutnya sensasi yang belum pernah ada sebelumnya.",
  ui_story_5059_50590102_31_dialog_content = "Tidak apa-apa. Ini terlalu mirip dengan ekorku sendiri. Dibandingkan dengan itu, aku lebih suka ulat.",
  ui_story_5059_50590102_32_dialog_content = "Mungkin Maggie bisa menikmati mereka di lapangan bersama Kanna lain kali.",
  ui_story_5059_50590102_33_dialog_content = "Selama ada cinta, naga dan manusia bisa bersama!",
  ui_story_5059_50590102_34_dialog_content = "Ya.",
  ui_story_5059_50590102_35_dialog_content = "Itu benar. Percikan antara Kobayashi dan saya adalah buktinya!",
  ui_story_5059_50590102_36_dialog_content = "Sudah kuduga…",
  ui_story_5059_50590102_37_dialog_content = "Benar juga, sih.",
  ui_story_5059_50590102_38_dialog_content = "Hubungan antara Tohru dan Kobayashi cukup membuat orang merasa iri.",
  ui_story_5059_50590102_39_dialog_content = "Tidak.",
  ui_story_5059_50590102_40_dialog_content = "Apa? Dengan jawaban itu, kau keberatan dengan cinta antara Kobayashi dan aku?",
  ui_story_5059_50590102_41_dialog_content = "Apakah Anda ingin merasakan kemarahan Naga yang disebut-sebut secara langsung?",
  ui_story_5059_50590102_42_dialog_content = "Tidak mungkin! Aku hanya secara tidak sengaja memilih jawaban yang salah, itu saja!",
  ui_story_5059_50590102_43_dialog_content = "Menikahi Kobayashi segera!",
  ui_story_5059_50590102_44_dialog_content = "Ya.",
  ui_story_5059_50590102_45_dialog_content = "Nah, di sana! Aku ingin tahu apakah kita bisa menikah di Astra?",
