  ui_story_5059_50590102_47_dialog_content = "Hehe, kebetulan saja aku membayangkannya di pikiranku, jadi aku bertanya karena penasaran.",
  ui_story_5059_50590102_48_dialog_content = "Kalau benar-benar ada upacara di sini, jangan lupa undang kami ya.",
