  ui_story_5059_50590102_59_dialog_content = "Apa katamu?",
  ui_story_5059_50590102_60_dialog_content = "Aku mengerti! Biarkan aku mencoba lagi.",
  ui_story_5059_50590102_61_dialog_content = "Saya terkesan. Kamu tahu lebih banyak tentang saya daripada yang saya bayangkan, PlayerName.",
  ui_story_5059_50590102_62_dialog_content = "Nah, itu karena Anda memiliki kepribadian yang berbeda dan sangat tak terlupakan.",
  ui_story_5059_50590102_63_dialog_content = "Tapi ternyata dua pertanyaan itu ada hubungannya dengan Kobayashi. Secara teknis, pertanyaan pertama juga demikian.",
  ui_story_5059_50590102_64_dialog_content = "Begitu besarnya cintaku pada Kobayashi.",
  ui_story_5059_50590102_65_dialog_content = "Dan bukan salahku bahwa Rapport Challenge 4 ini hanya bisa menerima tiga pertanyaan saja.",
