  ui_story_5059_50590102_69_dialog_content = "Aturan adalah aturan. Mereka ada untuk membuat permainan menjadi menyenangkan.",
  ui_story_5059_50590102_70_dialog_content = "Sebuah permainan seharusnya mendorong kamu untuk membuatnya lebih sulit agar kamu bisa menikmatinya lebih lagi. Itulah pesona dari bermain game.",
  ui_story_5059_50590102_71_dialog_content = "Jelas itu penjelasan yang aneh, namun entah bagaimana itu masuk akal.",
  ui_story_5059_50590102_72_dialog_content = "Jadi itulah tantangannya... Sepertinya aku sudah paham betul!",
  ui_story_5059_50590102_73_dialog_content = "Kamu benar-benar cepat belajar, Tohru.",
  ui_story_5059_50590102_74_dialog_content = "Bukan hanya aturan permainan. Terakhir kali saya mengajari dia cara membuat makanan penutup Astra yang populer dan dia menguasainya dengan cepat.",
  ui_story_5059_50590102_75_dialog_content = "Dan dia tidak mengalami masalah dalam memahami cara membuat ulat panggang rahasia Rediesel Wrench.",
  ui_story_5059_50590102_76_dialog_content = "Saya kan naga bangsawan, setelah semua!",
  ui_story_5059_50590102_77_dialog_content = "Makanan penutup boleh saja, tapi jangan pernah sajikan hal-hal seperti ulat pada Kobayashi!",
  ui_story_5059_50590102_78_dialog_content = "Ngomong-ngomong, sekarang bisakah kamu beritahu aku ke mana yang lain pergi?",
  ui_story_5059_50590102_79_dialog_content = "Tentu, izinkan saya untuk mundur ke sini.",
  ui_story_5059_50590102_80_dialog_content = "Aku ingat Elma menyeret Kanna bersamanya untuk mencari lebih banyak makanan.",
  ui_story_5059_50590102_81_dialog_content = "Lucoa bilang dia ingin mencari tempat yang bagus untuk beristirahat.",
  ui_story_5059_50590102_82_dialog_content = "Fafnir sudah pergi sebelum saya menyadari bahwa dia tidak ada di sekitar.",
  ui_story_5059_50590102_83_dialog_content = "Apa, hilang?",
  ui_story_5059_50590102_84_dialog_content = "Bisakah kamu membantuku menemukan semuanya, Tohru?",
  ui_story_5059_50590102_85_dialog_content = "Membantumu mencari mereka? Kurasa aku bisa.",
  ui_story_5059_50590102_86_dialog_content = "Aku akan mengasah keterampilan pembantu pembersihanku dan tidak akan meninggalkan satu pun yang terlewat, termasuk karpet.",
  ui_story_5059_50590103_1_dialog_content = "Kanna!",
  ui_story_5059_50590103_2_dialog_content = "Oh Kanna!",
  ui_story_5059_50590103_3_dialog_content = "Hmm, ini jalan yang kuingat dia lewati.",
  ui_story_5059_50590103_4_dialog_content = "Restoran Liu lebih besar dari yang kukira. Ini pertama kalinya aku di ruangan-ruangan ini.",
  ui_story_5059_50590103_5_dialog_content = "Tunggu, ada seseorang di bawah selimut.",
  ui_story_5059_50590103_6_dialog_content = "Mungkin Kanna sedang tidur siang.",
  ui_story_5059_50590103_7_dialog_content = "Bangun dan bersinar, Kanna!",
