  ui_story_5059_50590103_11_dialog_content = "Aku harus marah padamu karena membangunkanku dari mimpi di tempat tidur yang hangat!",
  ui_story_5059_50590103_12_dialog_content = "Maaf, aku kira itu Kanna di bawah penutupnya.",
  ui_story_5059_50590103_13_dialog_content = "*sniff* Apakah itu kamu, Lady Tohru dan PlayerName?",
  ui_story_5059_50590103_14_dialog_content = "Kanna? Kamu benar-benar bersembunyi di dalam selimut?",
  ui_story_5059_50590103_15_dialog_content = "Apa? Kapan Kanna masuk ke sana?",
  ui_story_5059_50590103_16_dialog_content = "Saat aku bermain petak umpet dengan Elma... Aku pikir akan nyaman jadi aku sembunyi di sini.",
  ui_story_5059_50590103_17_dialog_content = "Rasanya sangat nyaman di samping Nona Philyshy.",
  ui_story_5059_50590103_18_dialog_content = "PlayerName, PlayerName, Kanna memanggilku Kak!",
  ui_story_5059_50590103_19_dialog_content = "Aku dengar. Tidak perlu terlalu bersemangat.",
  ui_story_5059_50590103_20_dialog_content = "Kurasa kita harus menemukan Elma selanjutnya.",
  ui_story_5059_50590103_21_dialog_content = "Hanya sampai empat pemain yang bisa bermain game ini, PlayerName. Kenapa kita tidak main dulu dengan Kanna, lalu mencari Elma?",
  ui_story_5059_50590103_22_dialog_content = "Game? Aku juga mau main. Meow!",
  ui_story_5059_50590103_23_dialog_content = "Bagaimana cara yang benar untuk menyapa Tohru?",
