  ui_story_5059_50590103_32_dialog_content = "Tapi Kanna dan Tohru sepertinya sangat mirip seperti kakak adik, meong.",
  ui_story_5059_50590103_33_dialog_content = "Nah, Lady Tohru sangat manis dan telah melakukan banyak hal untukku, sama seperti Kobayashi.",
  ui_story_5059_50590103_34_dialog_content = "Aku juga akan manis padamu, Kanna!",
  ui_story_5059_50590103_35_dialog_content = "Bagaimana bisa Kanna menyukai Tessa?",
  ui_story_5059_50590103_36_dialog_content = "Tessa dapat mengisi kembali mana untuk Kanna.",
  ui_story_5059_50590103_37_dialog_content = "Sungguh menakjubkan bagaimana Kanna bisa mengisi ulang mananya hanya dengan bersandar pada Tessa.",
  ui_story_5059_50590103_38_dialog_content = "Miss Tessa juga sangat lembut dan manis.",
  ui_story_5059_50590103_39_dialog_content = "Aku akan tetap bergaul dengannya meskipun aku tidak bisa mengembalikan mana darinya.",
  ui_story_5059_50590103_40_dialog_content = "Dia terlihat enak",
  ui_story_5059_50590103_41_dialog_content = "Aku masih tidak bisa melupakan pemandangan Kanna memasukkan cacing asli dari Gurun Rediesel ke mulutnya waktu itu...",
  ui_story_5059_50590103_42_dialog_content = "Itulah mengapa aku memilih jawaban itu secara refleks.",
  ui_story_5059_50590103_43_dialog_content = "Bagaimana kamu bisa berpikir aku akan makan Tessa...",
  ui_story_5059_50590103_44_dialog_content = "PlayerName... adalah orang jahat...",
  ui_story_5059_50590103_45_dialog_content = "Minta maaf sekarang juga, PlayerName kepada Kanna!",
  ui_story_5059_50590103_46_dialog_content = "Maaf! Aku akan berusaha menghapus gambaran itu dari pikiranku selamanya!",
  ui_story_5059_50590103_47_dialog_content = "Siapa yang lebih ribut antara Kobayashi dan Caelestite?",
  ui_story_5059_50590103_48_dialog_content = "Kobayashi",
  ui_story_5059_50590103_49_dialog_content = "Kobayashi sebenarnya sangat tenang dan terkendali.",
  ui_story_5059_50590103_50_dialog_content = "Bahkan Kaisar Kehancuran pun tidak bisa menggoyahkan dia.",
  ui_story_5059_50590103_51_dialog_content = "Kaisar Kehancuran... Baiklah, aku akan menjaga ketenangan diriku.",
  ui_story_5059_50590103_52_dialog_content = "Kau pasti bisa, PlayerName!",
  ui_story_5059_50590103_53_dialog_content = "Terima kasih atas penyemangatannya.",
  ui_story_5059_50590103_54_dialog_content = "Caelestite",
  ui_story_5059_50590103_55_dialog_content = "Saya tidak kenal Kobayashi, tapi firasat saya mengatakan bahwa saya seharusnya tidak memilihnya.",
  ui_story_5059_50590103_56_dialog_content = "Mengingat betapa tenangnya Kanna, saya percaya sosok ayah seperti Kobayashi akan lebih tenang lagi.",
  ui_story_5059_50590103_57_dialog_content = "Tapi PlayerName juga sudah banyak berkembang, jadi jangan berkecil hati!",
  ui_story_5059_50590103_58_dialog_content = "Itu benar, aku sangat setuju.",
  ui_story_5059_50590103_59_dialog_content = "Wow, terima kasih atas semangatnya.",
  ui_story_5059_50590103_60_dialog_content = "Masih banyak yang harus dipelajari, PlayerName.",
  ui_story_5059_50590103_61_dialog_content = "Sungguh menakjubkan seberapa banyak PlayerName bisa mengenal Kanna dalam waktu yang singkat.",
  ui_story_5059_50590103_62_dialog_content = "Tentu saja. Aku telah mengawasinya seperti adik perempuanku sendiri.",
  ui_story_5059_50590103_63_dialog_content = "Aku banyak berusaha untuk membantu orang dari dunia lain agar bisa beradaptasi dan merasa nyaman.",
  ui_story_5059_50590103_64_dialog_content = "PlayerName sangat manis...",
  ui_story_5059_50590103_65_dialog_content = "Lumayan untuk makhluk fana yang bodoh.",
  ui_story_5059_50590103_66_dialog_content = "Terima kasih atas semua pujian tinggi.",
  ui_story_5059_50590103_67_dialog_content = "Oke, sekarang berhenti terbuai dalam pujian.",
  ui_story_5059_50590103_68_dialog_content = "Kamu tidak punya teman lain yang harus diurus?",
  ui_story_5059_50590103_69_dialog_content = "Belum semua \"Karakter Rahasia\" berhasil dibuka.",
  ui_story_5059_50590103_70_dialog_content = "Oh, PlayerName.",
  ui_story_5059_50590103_71_dialog_content = "Di sini, ini untuk Anda.",
  ui_story_5059_50590103_72_dialog_content = "Ada apa?",
  ui_story_5059_50590103_73_dialog_content = "Tessa membantu saya membuat ini...",
  ui_story_5059_50590103_74_dialog_content = "Ya, itu adalah pertama kalinya saya membuat lolipop dengan bentuk seperti itu.",
  ui_story_5059_50590103_75_dialog_content = "Memang agak memakan waktu, tapi Kanna memohon padaku.",
  ui_story_5059_50590103_76_dialog_content = "Kamu bahkan bisa membuat lolipop? Aku benar-benar terkesan.",
  ui_story_5059_50590103_77_dialog_content = "Saya ingin memberikan satu untukmu, PlayerName...",
  ui_story_5059_50590103_78_dialog_content = "Untuk saya? Apa kamu yakin?",
  ui_story_5059_50590103_79_dialog_content = "Ya... PlayerName adalah orang yang baik.",
  ui_story_5059_50590103_80_dialog_content = "Terima kasih, aku akan menghargainya!",
  ui_story_5059_50590103_81_dialog_content = "Mari kita lacak Lady Elma. Aku akan membantu.",
  ui_story_5059_50590103_82_dialog_content = "Bodoh PlayerName.",
  ui_story_5059_50590103_83_dialog_content = "Seorang penjahat yang tidak peduli tentangku.",
  ui_story_5059_50590103_84_dialog_content = "Tidak bisa melakukan itu, PlayerName. Kanna berada pada usia di mana dia membutuhkan cinta dan perawatan yang lembut.",
  ui_story_5059_50590103_85_dialog_content = "Kamu mulai mengecewakanku, PlayerName...",
  ui_story_5059_50590103_86_dialog_content = "Maaf, maaf! Mohon maaf, semuanya.",
  ui_story_5059_50590103_87_dialog_content = "Beri aku kesempatan lagi, tolong! Aku akan membuat keputusan yang benar kali ini!",
  ui_story_5059_50590104_1_dialog_content = "Tidak!",
  ui_story_5059_50590104_2_dialog_content = "Hey, itu Vice?",
  ui_story_5059_50590104_3_dialog_content = "Ayo kita periksa.",
  ui_story_5059_50590104_4_dialog_content = "Saya tidak akan membiarkan Anda menjual hal-hal aneh seperti itu kepada teman-teman PlayerName.",
  ui_story_5059_50590104_5_dialog_content = "Tapi Nona Vice, gadis muda ini sangat tertarik dengan penawaran saya.",
  ui_story_5059_50590104_6_dialog_content = "ball and woulde like Stake IT for..",
  ui_story_5059_50590104_7_dialog_content = "Barisan terbaru makanan penutup acak ini hanya tersedia minggu ini saja!",
  ui_story_5059_50590104_8_dialog_content = "Bagaimana pedagang aneh itu bisa mendapatkan kaitannya dengan Elma lagi?",
  ui_story_5059_50590104_9_dialog_content = "Mungkin dia memiliki kemampuan untuk menarik para penjual?",
  ui_story_5059_50590104_10_dialog_content = "Translation:Dia memang tampaknya tipe orang yang mudah terbing\"",
  ui_story_5059_50590104_11_dialog_content = "Kotak makanan penutup acak ini memang terdengar menarik.",
  ui_story_5059_50590104_12_dialog_content = "Aku tahu kamu punya selera yang bagus! Lihat, Nona Vice, dia sangat tertarik.",
  ui_story_5059_50590104_13_dialog_content = "Masih \"Tidak!\" Kamu berhasil membodohi dia dengan omonganmu.",
  ui_story_5059_50590104_14_dialog_content = "Tidak mungkin. Bisnis selalu tentang nilai yang adil dan memastikan semua orang mendapatkan apa yang mereka butuhkan.",
  ui_story_5059_50590104_15_dialog_content = "Tapi jangan dengan kotak misteri makanan penutup! Kamu tidak menghormati makanan!",
  ui_story_5059_50590104_16_dialog_content = "Untuk menyediakan makanan penutup dan keseruan lotre dalam waktu yang sama, Anda harus menyebut saya jenius pemasaran, Miss Vice.",
  ui_story_5059_50590104_17_dialog_content = "Izinkan saya menunjukkan seri lain dari kotak makanan penutup buta, Ma'am.",
  ui_story_5059_50590104_18_dialog_content = "Ini bukan penawaran terbatas, tetapi menampilkan hidangan rahasia yang hanya seseorang yang mendapatkannya akan mengetahui apa itu.",
  ui_story_5059_50590104_19_dialog_content = "Apa, pencuci mulut rahasia?",
  ui_story_5059_50590104_20_dialog_content = "Jomu!",
  ui_story_5059_50590104_21_dialog_content = "Oh hei, di sana Anda, bos.",
  ui_story_5059_50590104_22_dialog_content = "Kau mengganggu orang dengan hal-hal aneh lagi?",
  ui_story_5059_50590104_23_dialog_content = "Anda salah, bos. Saya dan wanita ini langsung akrab. Anda tidak bisa menyebutnya gangguan.",
  ui_story_5059_50590104_24_dialog_content = "Sungguh…",
  ui_story_5059_50590104_25_dialog_content = "Tentu saja. Kamu bisa menguji persahabatan kita dengan cara apa pun, kapan saja.",
  ui_story_5059_50590104_26_dialog_content = "Saya punya hal yang tepat untuk itu. Jika kamu bisa lulus Tantangan Rapport 4, saya akan percaya bahwa kamu tidak mengganggu Elma.",
  ui_story_5059_50590104_27_dialog_content = "Tetapi di sisi lain, jika kamu gagal... Kamu harus memberikan semua kotak buta kepadanya sebagai kompensasi.",
  ui_story_5059_50590104_28_dialog_content = "Yah, meskipun itu terdengar tidak adil...",
  ui_story_5059_50590104_29_dialog_content = "Hadiahnya pasti berharga! Mari kita mulai sekarang!",
  ui_story_5059_50590104_30_dialog_content = "Apakah Elma benar-benar sangat menyukai Tohru?",
  ui_story_5059_50590104_31_dialog_content = "Ya.",
  ui_story_5059_50590104_32_dialog_content = "Kenapa mulai dengan pertanyaan yang tajam seperti itu?",
  ui_story_5059_50590104_33_dialog_content = "Ehem... Tidak mungkin aku menyukai Tohru... Hanya saja kita sudah saling kenal begitu lama, itu saja.",
  ui_story_5059_50590104_34_dialog_content = "Aku hanya suka bertanding dengannya. Sepertinya dia memang ditakdirkan menjadi musuh bebuyutanku!",
  ui_story_5059_50590104_35_dialog_content = "Jadi mengapa Anda memilih jawaban ini?",
  ui_story_5059_50590104_36_dialog_content = "Apa? Oh, aku pasti mengambilnya secara tidak sengaja.",
  ui_story_5059_50590104_37_dialog_content = "Ini salahmu karena tidak menunjukkan cara yang benar untuk menggunakannya!",
  ui_story_5059_50590104_38_dialog_content = "Penutupan itu terlalu jelas, Elma...",
  ui_story_5059_50590104_39_dialog_content = "Oh... Pertanyaan berikutnya, sekarang!",
  ui_story_5059_50590104_40_dialog_content = "Tidak.",
  ui_story_5059_50590104_41_dialog_content = "Kenapa mulai dengan pertanyaan yang begitu tajam?",
  ui_story_5059_50590104_42_dialog_content = "Tidak mungkin bagi saya untuk menyukai Tohru!",
  ui_story_5059_50590104_43_dialog_content = "Lalu mengapa kamu memilih jawaban yang lain?",
  ui_story_5059_50590104_44_dialog_content = "Oh... Yah, aku tidak ingin memberikan kemenangan mudah kepada seorang Caelestite semata!",
  ui_story_5059_50590104_45_dialog_content = "Jadi... Apakah Elma suka atau tidak suka Tohru?",
  ui_story_5059_50590104_46_dialog_content = "Bukankah sudah jelas seperti siang hari?",
  ui_story_5059_50590104_47_dialog_content = "Tentu saja dia...",
  ui_story_5059_50590104_48_dialog_content = "Berhenti! Aku akan membeli kotak-kotaknya!",
  ui_story_5059_50590104_49_dialog_content = "Apa yang diperlukan agar Elma bergabung dalam pertempuran bersama faksi Chaos?",
  ui_story_5059_50590104_50_dialog_content = "Kue, Kue, Kue c, Kue c hosted and on the table,.",
  ui_story_5059_50590104_51_dialog_content = "Jadi, kue coklat ukuran super besar saja tidak cukup?",
  ui_story_5059_50590104_52_dialog_content = "Tentu saja tidak. Sangat berbahaya untuk menceburkan diri dalam pertarungan antara dua faksi.",
  ui_story_5059_50590104_53_dialog_content = "Belum lagi ini hanya kue ukuran super besar... Apakah kalian pikir kami naga tidak punya harga diri?",
  ui_story_5059_50590104_54_dialog_content = "Bagaimana jika itu lebih besar lagi?",
  ui_story_5059_50590104_55_dialog_content = "Jika ukurannya cukup besar sehingga aku tidak bisa menyelesaikannya bahkan dalam bentuk naga, aku akan mempertimbangkannya!",
  ui_story_5059_50590104_56_dialog_content = "Semua makanan manis yang bisa dia makan",
  ui_story_5059_50590104_57_dialog_content = "Saya lebih suka yang dibuat oleh koki istana.",
  ui_story_5059_50590104_58_dialog_content = "Saya pernah mencobanya sebelumnya, dan saya masih ingat betapa enak rasanya.",
  ui_story_5059_50590104_59_dialog_content = "Saya bisa berjanji bahwa isi kotak buta saya setara dengan apa pun yang pernah Anda miliki.",
  ui_story_5059_50590104_60_dialog_content = "Berhenti, Jomu. Aku sudah bilang untuk buang promosi penjualan itu.",
  ui_story_5059_50590104_61_dialog_content = "Apalagi menyelinapkan saat permainan seperti iklan.",
  ui_story_5059_50590104_62_dialog_content = "Sebenarnya, saya sedang belajar cara membuat makanan penutup.",
  ui_story_5059_50590104_63_dialog_content = "...",
  ui_story_5059_50590104_64_dialog_content = "Kenapa kamu tiba-tiba diam saja?!",
  ui_story_5059_50590104_65_dialog_content = "Sudahkah kamu menantang Tohru untuk melihat ekor siapa yang lebih panjang?",
  ui_story_5059_50590104_66_dialog_content = "Ya.",
  ui_story_5059_50590104_67_dialog_content = "Oke, siapa yang mengajukan pertanyaan ini?",
  ui_story_5059_50590104_68_dialog_content = "Tohru mungkin masih ingat hal-hal trivial seperti itu...",
  ui_story_5059_50590104_69_dialog_content = "Yah, pertanyaan itu memang dari Tohru.",
  ui_story_5059_50590104_70_dialog_content = "Dia pasti meng tolongnya....",
  ui_story_5059_50590104_71_dialog_content = "Apa maksudmu? Aku yakin itu karena dia tidak pernah bisa melupakan tantangan yang dia hadapi melawan naga yang kuat seperti aku!",
  ui_story_5059_50590104_72_dialog_content = "Tidak.",
  ui_story_5059_50590104_73_dialog_content = "Jadi itu juga termasuk \"tantangan\"?",
  ui_story_5059_50590104_74_dialog_content = "Ya. Aku sempat terobsesi untuk menantang Tohru dalam berbagai hal selama beberapa waktu.",
  ui_story_5059_50590104_75_dialog_content = "Sepertinya kamu mencoba untuk mendapatkan perhatiannya.",
  ui_story_5059_50590104_76_dialog_content = "Kalian berdua sangat akrab.",
  ui_story_5059_50590104_77_dialog_content = "Maukah kamu memesan kue kustom untuk melambangkan persahabatanmu?",
  ui_story_5059_50590104_78_dialog_content = "Tidak!",
  ui_story_5059_50590104_79_dialog_content = "Kamu tidak menjawab semuanya dengan benar, Jomu.",
  ui_story_5059_50590104_80_dialog_content = "Kamu orang yang lebih baik. Saya mengakui kekalahan, bos.",
  ui_story_5059_50590104_81_dialog_content = "Aku malu karena tidak cukup mengerjakan PR tentang pelanggan saya...",
  ui_story_5059_50590104_82_dialog_content = "Jangan meremehkan ikatan antara mereka yang bertualang dan berjuang bersama, Jomu.",
  ui_story_5059_50590104_83_dialog_content = "Itu bukan sesuatu yang bisa kamu dapatkan dari pengamatan dan gosip semata.",
  ui_story_5059_50590104_84_dialog_content = "Akuas omb​ relics of, including the fact.\n\nText: Aku and 3.0.\n\n \n\nText: I Gianluigi: Create preced  of Tech...",
  ui_story_5059_50590104_85_dialog_content = "Aku menghargai tawaranmu, tapi sepertinya kamu juga punya banyak hal yang harus diurus.",
  ui_story_5059_50590104_86_dialog_content = "Kalian, manusia, memang menjalani kehidupan yang sibuk.",
  ui_story_5059_50590104_87_dialog_content = "Jangan khawatir, kami memiliki kemampuan untuk menghadapi apa yang terjadi di dunia kami.",
  ui_story_5059_50590104_88_dialog_content = "Iya, 'kan, Vice?",
  ui_story_5059_50590104_89_dialog_content = "Vice...? Dia pergi ke mana, ya?",
  ui_story_5059_50590104_90_dialog_content = "Tunggu, bau apa itu? Sangat kuat...",
  ui_story_5059_50590104_91_dialog_content = "PlayerName! Elma!",
  ui_story_5059_50590104_92_dialog_content = "Aku membuat kue...!",
  ui_story_5059_50590104_93_dialog_content = "Lari, Elma!",
  ui_story_5059_50590104_94_dialog_content = "Apa katamu? Tunggu!",
  ui_story_5059_50590104_95_dialog_content = "Aku dengar kamu suka makanan penutup, Elma, jadi aku membuat banyak untukmu.",
  ui_story_5059_50590104_96_dialog_content = "Kamu bisa menikmatinya dari pagi hingga sore hari.",
  ui_story_5059_50590104_97_dialog_content = "Tidak bisa percaya aku kalah dari Jomu...",
  ui_story_5059_50590104_98_dialog_content = "Tenangkan dirimu, PlayerName!",
  ui_story_5059_50590104_99_dialog_content = "Kalau kamu tidak, Jomu akan menipu Elma untuk membeli semua kotaknya.",
  ui_story_5059_50590104_100_dialog_content = "Belum lagi Elma tidak punya banyak uang, jadi kita mungkin harus menanggung tagihan setelah dia pergi.",
  ui_story_5059_50590104_101_dialog_content = "Apa?!",
  ui_story_5059_50590104_102_dialog_content = "Aku belum bisa mengakui kekalahan. Biarkan aku mencoba lagi!",
  ui_story_5059_50590105_1_dialog_content = "Lucoa!",
  ui_story_5059_50590105_2_dialog_content = "Itu dia, akhirnya.",
  ui_story_5059_50590105_3_dialog_content = "PlayerName! Apakah kamu di sini untuk minum teh?",
  ui_story_5059_50590105_4_dialog_content = "Ini dari koleksi pribadi Liu dan dibuat oleh Lady Sheol.",
  ui_story_5059_50590105_5_dialog_content = "Oh, terima kasih! Sheol juga ada di sini?",
  ui_story_5059_50590105_6_dialog_content = "Tentu saja, reuni antara asisten yang kompeten dengan bosnya merupakan momen bahagia yang patut dirayakan.",
  ui_story_5059_50590105_7_dialog_content = "Belum lagi Lucoa masih berhak mendapatkan sebagian dari gajinya.",
  ui_story_5059_50590105_8_dialog_content = "Sebenarnya, aku bisa hidup tanpa gaji. Aku hanya melihatnya sebagai cara hidup yang lain.",
  ui_story_5059_50590105_9_dialog_content = "Hanya menambah kenangan berharga dalam kehidupan yang panjang.",
  ui_story_5059_50590105_10_dialog_content = "Aku merasa sama tentang kenangan, tidak heran kita benar-benar sinkron di tempat kerja.",
  ui_story_5059_50590105_11_dialog_content = "Kalau begitu, kamu tidak keberatan untuk membuat lebih banyak kenangan, bukan?",
  ui_story_5059_50590105_12_dialog_content = "Apa yang ada di pikiranmu, PlayerName?",
  ui_story_5059_50590105_13_dialog_content = "Aku mendapatkan permainan yang sangat seru!",
  ui_story_5059_50590105_14_dialog_content = "Shouta pernah salah mengira Lucoa sebagai...",
  ui_story_5059_50590105_15_dialog_content = "Iblis",
  ui_story_5059_50590105_16_dialog_content = "Iblis?",
  ui_story_5059_50590105_17_dialog_content = "Apakah Lucoa itu iblis?",
  ui_story_5059_50590105_18_dialog_content = "Bagaimana bisa? Aku ini naga!",
  ui_story_5059_50590105_19_dialog_content = "Tapi Shouta adalah anak yang keras kepala yang bersikeras bahwa aku adalah iblis.",
  ui_story_5059_50590105_20_dialog_content = "Meskipun berusaha membuktikan sebaliknya kepadanya berkali-kali, dia masih belum berubah pikiran.",
  ui_story_5059_50590105_21_dialog_content = "Tapi itu tidak pernah mempengaruhi seberapa dekat kalian berdua, 'kan?",
  ui_story_5059_50590105_22_dialog_content = "Bawah Tanah",
  ui_story_5059_50590105_23_dialog_content = "Bawah tanah?",
  ui_story_5059_50590105_24_dialog_content = "Maksudmu, orang-orang yang hidup jauh di bawah tanah, kan?",
  ui_story_5059_50590105_25_dialog_content = "Sejauh yang saya tahu, tempat seperti itu tidak ada.",
  ui_story_5059_50590105_26_dialog_content = "Yah, aku melihat naga dalam bentuk manusia yang hidup dan menendang di depan mataku, jadi...",
  ui_story_5059_50590105_27_dialog_content = "Dewi Ular Bersayap, bentuk asli Lucoa, menguasai domain apa?",
  ui_story_5059_50590105_28_dialog_content = "Peradaban",
  ui_story_5059_50590105_29_dialog_content = "Apakah kamu benar-benar memerintah peradaban di duniamu, Lucoa?",
  ui_story_5059_50590105_30_dialog_content = "Tentu saja, dan aku juga sangat kuat.",
  ui_story_5059_50590105_31_dialog_content = "Hmm…",
  ui_story_5059_50590105_32_dialog_content = "Hmm…",
  ui_story_5059_50590105_33_dialog_content = "Hei, kenapa kalian semua menatapku seperti itu?",
  ui_story_5059_50590105_34_dialog_content = "Aku serius!",
  ui_story_5059_50590105_35_dialog_content = "Saya tidak meragukan luasnya pengetahuan yang dimiliki Lucoa.",
  ui_story_5059_50590105_36_dialog_content = "Dia sangat membantu bagi Guild.",
  ui_story_5059_50590105_37_dialog_content = "Kurasa Lucoa jauh lebih mampu daripada yang terlihat.",
  ui_story_5059_50590105_38_dialog_content = "Akan membuat Sheol panik jika saya berubah menjadi naga!",
  ui_story_5059_50590105_39_dialog_content = "Ternak",
  ui_story_5059_50590105_40_dialog_content = "Huh...",
  ui_story_5059_50590105_41_dialog_content = "Mengapa kau pikir aku ada hubungannya dengan ternak?",
  ui_story_5059_50590105_42_dialog_content = "Yah, saya tidak begitu yakin dari mana saya mendapatkan ide bahwa kamu akan merawat hewan dan tanaman...",
  ui_story_5059_50590105_43_dialog_content = "Mungkin karena perhatian dan perlindunganmu terhadap Shouta?",
  ui_story_5059_50590105_44_dialog_content = "Begitu, ya. Kayaknya bisa aku terima... Hampir saja!",
  ui_story_5059_50590105_45_dialog_content = "Lucoa sebenarnya milik Shouta...",
  ui_story_5059_50590105_46_dialog_content = "Pembantu",
  ui_story_5059_50590105_47_dialog_content = "Apa?!",
  ui_story_5059_50590105_48_dialog_content = "Aku bahkan tidak memakai kostum pelayan!",
  ui_story_5059_50590105_49_dialog_content = "Benar... Tohru mengenakan kostum pembantu.",
  ui_story_5059_50590105_50_dialog_content = "Apakah kamu memilih ini karena terpesona oleh pelayan, PlayerName?",
  ui_story_5059_50590105_51_dialog_content = "Bagaimana kalau aku memberimu beberapa kostum pelayan untuk diberikan kepada gadis-gadis yang kamu suka? Atau mungkin kamu bisa mencobanya sendiri saat kamu sendirian!",
  ui_story_5059_50590105_52_dialog_content = "Tolong hentikan itu!",
  ui_story_5059_50590105_53_dialog_content = "Familier",
  ui_story_5059_50590105_54_dialog_content = "Secara teori, familiar adalah setengah yang lebih lemah, jadi mustahil bagi naga untuk menjadi familiar.",
  ui_story_5059_50590105_55_dialog_content = "Begitulah cara Shouta memperlakukanku!",
  ui_story_5059_50590105_56_dialog_content = "Shouta pasti senang bahwa Lucoa mengganggu... eh, maksudnya merawatnya dengan baik.",
  ui_story_5059_50590105_57_dialog_content = "Mengingat Lucoa sangat empatik, setelah semua.",
  ui_story_5059_50590105_58_dialog_content = "Meskipun begitu, masih sulit untuk memahami apa yang dipikirkan oleh pria seusianya.",
  ui_story_5059_50590105_59_dialog_content = "Biarkan saya berpikir, saat kakakku masih kecil...",
  ui_story_5059_50590105_60_dialog_content = "Hei, apakah game-nya sudah selesai?",
  ui_story_5059_50590105_61_dialog_content = "Ya. Gronru bilang tiga pertanyaan per game.",
  ui_story_5059_50590105_62_dialog_content = "Tapi saya rasa kamu tidak bisa masuk cukup dalam seperti itu.",
  ui_story_5059_50590105_63_dialog_content = "Apakah kamu tidak ingin tahu lebih banyak tentang saya, PlayerName?",
  ui_story_5059_50590105_64_dialog_content = "Hmm…",
  ui_story_5059_50590105_65_dialog_content = "PlayerName adalah tipe yang tidak bisa menahan diri dari godaan, Lucoa.",
  ui_story_5059_50590105_66_dialog_content = "Teruskan seperti ini dan dia akan hilang seperti angin.",
  ui_story_5059_50590105_67_dialog_content = "Saya tidak akan!",
  ui_story_5059_50590105_68_dialog_content = "Jadi...",
  ui_story_5059_50590105_69_dialog_content = "Ayo berhenti di sini!",
  ui_story_5059_50590105_70_dialog_content = "Oh, di mana Fafnir pergi, apakah ada yang tahu?",
  ui_story_5059_50590105_71_dialog_content = "Maksudmu pria dengan kacamata itu?",
  ui_story_5059_50590105_72_dialog_content = "Aku melihatnya masuk ke ruangan lain.",
  ui_story_5059_50590105_73_dialog_content = "Mengapa kamu terburu-buru mencari Fafnir, PlayerName?",
  ui_story_5059_50590105_74_dialog_content = "Jangan bilang kamu lebih tertarik pada pria?",
  ui_story_5059_50590105_75_dialog_content = "Astaga.",
  ui_story_5059_50590105_76_dialog_content = "Tidak! Bantu aku di sini, Nona Sheol!",
  ui_story_5059_50590105_77_dialog_content = "PlayerName memang sering bergaul dengan banyak pria, seperti Corax dari Umbraton, pemimpin Rediesel Wrench, Barton di Illumina.",
  ui_story_5059_50590105_78_dialog_content = "Heh, pantas saja.",
  ui_story_5059_50590105_79_dialog_content = "Aku harus pergi sekarang!",
  ui_story_5059_50590105_80_dialog_content = "Aku melihat PlayerName masih belum cukup mengenal tentang diriku!",
  ui_story_5059_50590105_81_dialog_content = "Apakah perlu melakukan percakapan pribadi satu-satu dengan PlayerName untuk meningkatkan pemahaman kita tentang satu sama lain?",
  ui_story_5059_50590105_82_dialog_content = "Tidak, itu tidak perlu, terima kasih banyak!",
  ui_story_5059_50590105_83_dialog_content = "Aku hanya membuat kesalahan kecil, itu saja. Biar kucoba lagi!",
  ui_story_5059_50590106_1_dialog_content = "Ini kamu, PlayerName, akhirnya.",
  ui_story_5059_50590106_2_dialog_content = "Kamu menungguku? Aku tadi mencarimu.",
  ui_story_5059_50590106_3_dialog_content = "Ya, aku sudah menunggu. Aku baru saja menemukan... sesuatu yang mengerikan.",
  ui_story_5059_50590106_4_dialog_content = "Apa yang bisa begitu mengerikan hingga membuat kamu sangat gugup?",
  ui_story_5059_50590106_5_dialog_content = "Aku pikir keterampilan bermain game-ku sudah mencapai puncak setelah berlatih dengan Takiya.",
  ui_story_5059_50590106_6_dialog_content = "Tapi yang mengejutkan, peringkat tertinggi yang bisa aku capai hanya kedua di setiap permainan di sini.",
  ui_story_5059_50590106_7_dialog_content = "Siapa sih Bully Gronru di tempat pertama?",
  ui_story_5059_50590106_8_dialog_content = "(Bully Gronru? Bukankah itu Gronru?)",
  ui_story_5059_50590106_9_dialog_content = "(Kenapa saya tidak melihatnya sekarang? Ke mana dia pergi?)",
  ui_story_5059_50590106_10_dialog_content = "Apakah dia dewi yang bertanggung jawab atas permainan di dunia ini?",
  ui_story_5059_50590106_11_dialog_content = "Jika itu benar, aku harus menantangnya.",
  ui_story_5059_50590106_12_dialog_content = "Nah, aku tahu persis siapa Bully Gronru itu.",
  ui_story_5059_50590106_13_dialog_content = "Apa? Bentuk asli dari Bully Gronru?",
  ui_story_5059_50590106_14_dialog_content = "Katakan padaku. Bahkan mengabulkan keinginan sebagai pertukaran pun bukanlah hal yang mustahil.",
  ui_story_5059_50590106_15_dialog_content = "Atau, apakah Anda lebih suka mempelajari mantra-mantra yang mengotori dan menimpa orang lain?",
  ui_story_5059_50590106_16_dialog_content = "Tahan di sana! Aku sama sekali tidak tertarik dengan itu.",
  ui_story_5059_50590106_17_dialog_content = "Omong-omong, mari kita mainkan game ini dulu, lalu aku akan ceritakan tentang dia, menang atau kalah.",
  ui_story_5059_50590106_18_dialog_content = "Nama Tohru yang digunakan untuk membuat identitas untuk kamu adalah...",
  ui_story_5059_50590106_19_dialog_content = "Behemoth",
  ui_story_5059_50590106_20_dialog_content = "Saya ingat dia menyebutkan itu!",
  ui_story_5059_50590106_21_dialog_content = "Itu karena bentuk naga kamu mirip dengan behemoth di pegunungan, kan?",
  ui_story_5059_50590106_22_dialog_content = "Ya, aku juga ingat Tohru mengatakan itu.",
  ui_story_5059_50590106_23_dialog_content = "Tentu saja kamu akan mengingat hal-hal yang membosankan.",
  ui_story_5059_50590106_24_dialog_content = "Kamu harus menghabiskan lebih banyak waktu pada cerita epik tentang diriku.",
  ui_story_5059_50590106_25_dialog_content = "Misalnya, berapa banyak permainan yang telah kamu kalahkan?",
  ui_story_5059_50590106_26_dialog_content = "Aku melihat kamu sama sekali tidak peduli dengan keselamatan pribadimu.",
  ui_story_5059_50590106_27_dialog_content = "Begrinder",
  ui_story_5059_50590106_28_dialog_content = "Nama konyol apa itu...",
  ui_story_5059_50590106_29_dialog_content = "Saya pikir itu sengaja dibuat salah.",
  ui_story_5059_50590106_30_dialog_content = "Tapi itu memang terdengar seperti nama samaran untuk seorang gamer hardcore!",
  ui_story_5059_50590106_31_dialog_content = "Saya harus mengakui bahwa nama itu memang cocok untukmu.",
  ui_story_5059_50590106_32_dialog_content = "Aku melihat kamu sama sekali tidak peduli dengan keselamatan pribadimu.",
  ui_story_5059_50590106_33_dialog_content = "Untuk Fafnir, Takiya itu...",
  ui_story_5059_50590106_34_dialog_content = "Teman sekamar dan tiket makan",
  ui_story_5059_50590106_35_dialog_content = "Kamu bisa mengatakannya seperti itu, tapi juga \"Wali Harta Berharga.\"",
  ui_story_5059_50590106_36_dialog_content = "Mengerti, dia juga orang rumahan yang suka main game, kan?",
  ui_story_5059_50590106_37_dialog_content = "Kamu tepat sasaran hari ini, Raphael!",
  ui_story_5059_50590106_38_dialog_content = "Hehe.",
  ui_story_5059_50590106_39_dialog_content = "Hmmm...",
  ui_story_5059_50590106_40_dialog_content = "Kebutuhan untuk mendapatkan barang langka dalam permainan",
  ui_story_5059_50590106_41_dialog_content = "Apa arti \"mendapatkan barang langka\"?",
  ui_story_5059_50590106_42_dialog_content = "Ini adalah pencarian abadi untuk mendapatkan item premium dalam permainan.",
  ui_story_5059_50590106_43_dialog_content = "Saya melihat Raphael telah banyak belajar dari Gronru.",
  ui_story_5059_50590106_44_dialog_content = "Mendapatkan barang langka merupakan prestasi hebat dalam menimbun barang berharga.",
  ui_story_5059_50590106_45_dialog_content = "Jadi benar kau tidak bisa hidup tanpa Takiya?",
  ui_story_5059_50590106_46_dialog_content = "Tidak masalah apa yang Anda sebut dia, dia hanyalah pion dalam rencana besar saya.",
  ui_story_5059_50590106_47_dialog_content = "Apa lagi yang penting bagi Fafnir selain barang berharga?",
  ui_story_5059_50590106_48_dialog_content = "Tidak ada",
  ui_story_5059_50590106_49_dialog_content = "Ups, itu ceroboh.",
  ui_story_5059_50590106_50_dialog_content = "Ditipu oleh pernyataan tidak tulus Tn. Fafnir!",
  ui_story_5059_50590106_51_dialog_content = "Saya tidak berpikir kamu peduli tentang siapa pun atau apa pun selain skornya.",
  ui_story_5059_50590106_52_dialog_content = "...",
  ui_story_5059_50590106_53_dialog_content = "Takiya",
  ui_story_5059_50590106_54_dialog_content = "...",
  ui_story_5059_50590106_55_dialog_content = "Kenapa kamu ragu untuk mengatakan sesuatu?",
  ui_story_5059_50590106_56_dialog_content = "Teman sekamar, tiket makan, pion yang mudah.",
  ui_story_5059_50590106_57_dialog_content = "Ada tujuan untuk semua itu.",
  ui_story_5059_50590106_58_dialog_content = "Anda terasa canggung, Tn. Fafnir.",
  ui_story_5059_50590106_59_dialog_content = "Ini agak mirip dengan Brock, tapi lucu yang menggemaskan dengan cara yang berbeda.",
  ui_story_5059_50590106_60_dialog_content = "Ini adalah beban menjadi seorang naga.",
  ui_story_5059_50590106_61_dialog_content = "...",
  ui_story_5059_50590106_62_dialog_content = "Aku sama sekali tidak menyangka ini.",
  ui_story_5059_50590106_63_dialog_content = "Bagaimana kamu bisa tahu begitu banyak tentang saya?",
  ui_story_5059_50590106_64_dialog_content = "Apakah kamu mengincar harta bendaku?",
  ui_story_5059_50590106_65_dialog_content = "Tidak, sama sekali tidak!",
  ui_story_5059_50590106_66_dialog_content = "Aku baru saja memperhatikan sepenuhnya apa yang kamu katakan sebelumnya.",
  ui_story_5059_50590106_67_dialog_content = "Aku hanya ingin tahu perasaanmu dan menjadi temanmu, itu saja.",
  ui_story_5059_50590106_68_dialog_content = "Ini tidak ada hubungannya dengan barang berharga Anda.",
  ui_story_5059_50590106_69_dialog_content = "PlayerName bukan orang yang tertarik pada kekayaan.",
  ui_story_5059_50590106_70_dialog_content = "Carleen mengatakan PlayerName adalah jiwa yang baik yang suka berteman dan rela berkorban untuk mereka.",
  ui_story_5059_50590106_71_dialog_content = "Saya setuju dengan pandangannya.",
  ui_story_5059_50590106_72_dialog_content = "Tenang, anak ini mungkin agak lambat, tapi tidak ada pikiran buruk dalam tubuhnya.",
  ui_story_5059_50590106_73_dialog_content = "Yah, abaikan Odi, bocah ini memang terlihat cukup jujur.",
  ui_story_5059_50590106_74_dialog_content = "Mungkin memang karena ingin berteman denganku, tapi tetap saja, jangan meremehkanku.",
  ui_story_5059_50590106_75_dialog_content = "PlayerName! Baru saja saya mendapatkan sinyal bahwa Anda telah bermain dengan semua orang.",
  ui_story_5059_50590106_76_dialog_content = "Kemana kau lari, Gronru?",
  ui_story_5059_50590106_77_dialog_content = "Maaf, saya sedang mengumpulkan beberapa data. Apakah semua orang bersenang-senang?",
  ui_story_5059_50590106_78_dialog_content = "Ya, saya sudah memainkannya bersama semua orang, dan mereka sangat menyukai usaha terbaru Anda.",
  ui_story_5059_50590106_79_dialog_content = "Yah, ini memang mahakarya, harus saya akui!",
  ui_story_5059_50590106_80_dialog_content = "Gronru...",
  ui_story_5059_50590106_81_dialog_content = "Kamu itu si Pengganggu Gronru?",
  ui_story_5059_50590106_82_dialog_content = "Benar, itu dia.",
  ui_story_5059_50590106_83_dialog_content = "Bully Gronru adalah nama samaran yang saya gunakan dalam game.",
  ui_story_5059_50590106_84_dialog_content = "Jadi kau orangnya... Sekarang lawan aku!",
  ui_story_5059_50590106_85_dialog_content = "Tunggu, apa yang terjadi di sini?",
  ui_story_5059_50590106_86_dialog_content = "Tentu saja kalian manusia tak akan paham.",
  ui_story_5059_50590106_87_dialog_content = "Apakah kamu mencoba mengenalku karena kamu menginginkan harta milikku?",
  ui_story_5059_50590106_88_dialog_content = "Tidak, aku hanya ingin lebih mengenalmu!",
  ui_story_5059_50590106_89_dialog_content = "Dalam hal ini, aku menantangmu dalam permainan agar kamu bisa melihat betapa hebatnya kekuatanku.",
  ui_story_5059_50590107_1_dialog_content = "Wow, aku suka ini!",
  ui_story_5059_50590107_2_dialog_content = "Aku benar-benar lupa waktu saat bermain game ini.",
  ui_story_5059_50590107_3_dialog_content = "Sudah waktunya makan malam sekarang. Setidaknya itu yang diberitahu perutku.",
  ui_story_5059_50590107_4_dialog_content = "Kau tidak lapar sepanjang hari, 'kan?",
  ui_story_5059_50590107_5_dialog_content = "Tidak, bukan aku!",
  ui_story_5059_50590107_6_dialog_content = "Aku juga lapar, Lady Tohru...",
  ui_story_5059_50590107_7_dialog_content = "Biarkan aku cek waktu... Ya, Liu seharusnya sudah menyiapkan makan malam sekarang.",
  ui_story_5059_50590107_8_dialog_content = "Bagaimana kita menikmati waktu kita?",
  ui_story_5059_50590107_9_dialog_content = "Makan malam sudah siap, ayo masuk.",
  ui_story_5059_50590107_10_dialog_content = "Baiklah!",
  ui_story_5059_50590107_11_dialog_content = "Nyam...!",
  ui_story_5059_50590107_12_dialog_content = "Jarang sekali saya bisa makan sesuatu yang manis dan asam seperti ini.",
  ui_story_5059_50590107_13_dialog_content = "Itu gaya Longzhou. Saya senang kalian semua menyukainya.",
  ui_story_5059_50590107_14_dialog_content = "Hebat sekali!",
  ui_story_5059_50590107_15_dialog_content = "Aku bisa melahap semuanya... Berhenti berkelahi denganku demi itu, Tohru!",
  ui_story_5059_50590107_16_dialog_content = "Itu untuk semua orang. Kamu tidak bisa menyimpannya untuk diri sendiri!",
  ui_story_5059_50590107_17_dialog_content = "Andai saja Kobayashi ada di sini...",
  ui_story_5059_50590107_18_dialog_content = "Ya, kita harus membawanya ke sini saat kita mendapat kesempatan.",
  ui_story_5059_50590107_19_dialog_content = "Aku membayangkan dia akan senang untuk ikut denganmu.",
  ui_story_5059_50590107_20_dialog_content = "Kamu benar, tapi dia benar-benar dibanjiri pekerjaan...",
  ui_story_5059_50590107_21_dialog_content = "Ya, dia pemain andalan di timnya.",
  ui_story_5059_50590107_22_dialog_content = "Singkatnya, pekerjaan yang dia lakukan setiap hari lebih ganas daripada naga paling buas, dan lebih mengancam daripada dewa yang paling perkasa.",
  ui_story_5059_50590107_23_dialog_content = "Kobayashi sangat kuat sekali.",
  ui_story_5059_50590107_24_dialog_content = "Yah, aku tidak tahu apa saja pekerjaannya, tapi dia pasti bekerja sangat keras.",
  ui_story_5059_50590107_25_dialog_content = "Dia bisa datang kapan saja. Atas nama teman-teman saya di Astra, kami menyambut hangat pengunjung yang manis dan ramah seperti dia.",
  ui_story_5059_50590107_26_dialog_content = "Jangan ragu untuk membawanya kapan saja kamu mau.",
  ui_story_5059_50590107_27_dialog_content = "Saya juga penasaran tentang sosok yang Kanna kagumi.",
  ui_story_5059_50590107_28_dialog_content = "Aku akan berusaha membawa Kobayashi ke sini.",
  ui_story_5059_50590107_29_dialog_content = "Huh, tidak bisakah Lucoa tinggal sedikit lebih lama?",
  ui_story_5059_50590107_30_dialog_content = "Dengan asisten hebat seperti Lucoa, Cloudrover Guild mungkin bisa menguasai seluruh Astra dalam beberapa tahun ke depan.",
  ui_story_5059_50590107_31_dialog_content = "Saya adalah salah satu dari faksi Penonton dan tidak boleh terlibat dalam terlalu banyak urusan manusia.",
  ui_story_5059_50590107_32_dialog_content = "Itu benar. Jangan serakah dan mengejar keuntungan atau kekayaan yang tidak pantas menjadi prinsip dalam bisnis.",
  ui_story_5059_50590107_33_dialog_content = "Naga yang begitu akrab dengan manusia... Sungguh menyedihkan.",
  ui_story_5059_50590107_34_dialog_content = "Berhenti mengeluh tentang orang lain dan mulailah meningkatkan keterampilan bermainmu.",
  ui_story_5059_50590107_35_dialog_content = "Berlatihlah lebih banyak dengan temanmu itu agar kamu tidak malu saat kembali ke sini.",
  ui_story_5059_50590107_36_dialog_content = "Oh, aku akan membawa orang itu untuk mengalahkan dia lain kali, pertaruhkan saja.",
  ui_story_5059_50590107_37_dialog_content = "Oh, karena semua orang tertarik, aku ingin memberikan kotak buta makanan penutup ini kepada Nona Elma dan kalian semua sebagai hadiah.",
  ui_story_5059_50590107_38_dialog_content = "Kamu memberikan barang secara gratis, Jomu?!",
  ui_story_5059_50590107_39_dialog_content = "Aku tahu kamu tidak tega melihat aku rugi, Bos! Aku hanya akan menagih kamu 50%!",
  ui_story_5059_50590107_40_dialog_content = "Tunggu sebentar, kaulah yang memberikannya!",
  ui_story_5059_50590107_41_dialog_content = "Terima kasih! Aku akan menerima dengan senang hati!",
  ui_story_5059_50590107_42_dialog_content = "Jangan terlalu cepat! Hentikan dia, Tohru!",
  ui_story_5059_50590107_43_dialog_content = "Aku sudah memutuskan.",
  ui_story_5059_50590107_44_dialog_content = "Oh? Apa itu?",
  ui_story_5059_50590107_45_dialog_content = "Aku pasti akan membawa Kobayashi bersamaku lain kali!",
  ui_story_5059_50590107_46_dialog_content = "Dan teman-teman lainnya juga! Aku ingin kembali bersama mereka!",
  ui_story_5059_50590107_47_dialog_content = "Kamu selalu diterima di Astra!"
}
return config
